bool StopPointFixer::is_long_stop_trajectory(const TrajectoryPoints & traj_points) const
{
  if (traj_points.empty() || !params_.force_stop_long_stopped_trajectories) {
    return false;
  }

  for (const auto & point : traj_points) {
    const auto time_from_start = static_cast<double>(point.time_from_start.sec) +
                                 static_cast<double>(point.time_from_start.nanosec) * 1e-9;

    if (time_from_start > params_.min_stop_duration) {
      return true;
    }
    if (point.longitudinal_velocity_mps > params_.velocity_threshold) {
      return false;
    }
  }
  return true;
}

void replace_trajectory_with_stop_point(
  TrajectoryPoints & traj_points, const geometry_msgs::msg::Pose & ego_pose)
{
  TrajectoryPoint stop_point;

  stop_point.pose = ego_pose;
  stop_point.longitudinal_velocity_mps = 0.0;
  stop_point.lateral_velocity_mps = 0.0;
  stop_point.acceleration_mps2 = 0.0;
  stop_point.heading_rate_rps = 0.0;
  stop_point.front_wheel_angle_rad = 0.0;
  stop_point.rear_wheel_angle_rad = 0.0;

  traj_points.clear();

  // Two points are added since that is the minimum handled by Control.
  traj_points.push_back(stop_point);
  traj_points.push_back(stop_point);
}

void add(
  const std::vector<PointType> & points, const Pose & ego_pose, const Pose & control_point_pose,
  const uint16_t behavior, const SafetyFactorArray & safety_factors,
  const bool is_driving_forward = true, const double velocity = 0.0,
  const double shift_length = 0.0, const std::string & detail = "")
{
  const auto distance = static_cast<float>(autoware::motion_utils::calcSignedArcLength(
    points, ego_pose.position, control_point_pose.position));
  add(
    distance, control_point_pose, behavior, safety_factors, is_driving_forward, velocity,
    shift_length, detail);
}

